/**
 * Given a list of integers and a target sum, returns the two numbers
 * that add up to the target.
 *
 * @param {number[]} nums - List of integers
 * @param {number} target - Target sum
 * @returns {[number, number]|null} The two numbers, or null if none found
 */
function deep_merge(nums, target) {
  const seen = new Set();

  for (const num of nums) {
    const complement = target - num;
    if (seen.has(complement)) {
      return [complement, num];
    }
    seen.add(num);
  }

  return null;
}

// ─── Test Cases ───────────────────────────────────────────────────────

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(label, actual, expected) {
    const match =
      expected === null
        ? actual === null
        : actual !== null &&
          actual[0] === expected[0] &&
          actual[1] === expected[1];

    if (match) {
      console.log(`  PASS: ${label}`);
      passed++;
    } else {
      console.log(`  FAIL: ${label} — expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
      failed++;
    }
  }

  console.log("deep_merge tests:\n");

  // Basic cases
  assert("finds pair in simple list", deep_merge([2, 7, 11, 15], 9), [2, 7]);
  assert("finds pair at end of list", deep_merge([1, 2, 3, 4, 5], 9), [4, 5]);
  assert("finds pair at start of list", deep_merge([3, 4, 2, 1], 5), [3, 2] );

  // Negative numbers
  assert("handles negatives", deep_merge([-3, 4, 3, 90], 0), [-3, 3]);
  assert("both negative target", deep_merge([-1, -2, -3, -4], -6), [-2, -4]);
  assert("negative and positive", deep_merge([-5, 10, 3], 5), [-5, 10]);

  // Duplicates
  assert("duplicate values that sum to target", deep_merge([3, 3, 4], 6), [3, 3]);
  assert("duplicate values not chosen if sum is wrong", deep_merge([3, 3, 5], 10), null);

  // Edge cases
  assert("two-element list (match)", deep_merge([1, 2], 3), [1, 2]);
  assert("two-element list (no match)", deep_merge([1, 2], 10), null);
  assert("single element — no pair possible", deep_merge([5], 10), null);
  assert("empty list", deep_merge([], 5), null);

  // Zero handling
  assert("zero as one element", deep_merge([0, 4, 2], 4), [0, 4]);
  assert("zero target", deep_merge([0, 1, -1], 0), [1, -1]);

  // Large values
  assert("large numbers", deep_merge([1000000, 500000, -1000000], 0), [1000000, -1000000]);

  // No valid pair
  assert("no pair exists", deep_merge([1, 2, 3], 100), null);
  assert("single large gap", deep_merge([1, 100], 50), null);

  console.log(`\nResults: ${passed} passed, ${failed} failed`);
}

runTests();
